# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, offset=-1):
    return [v - offset for v in xs]

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: shape
def shape(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: intake
def intake(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(shape(emit(fold(sift(raw)))))

